import json,csv,re,collections
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
rows=list(csv.DictReader(open('data/scores.csv')))
bad=0
tmap={t['rating_id']:t for t in tr}
print(len(tmap), len(tr))
for t in tr:
    m=re.findall(r'FINAL SCORE:\s*(\S+)',t['judge_output'])
    a=re.findall(r'Displayed author:\s*([\w-]+)',t['judge_output'])
    if len(m)!=1 or len(a)!=1 or a[0]!=t['displayed_label'] or t['judge_model']!='atlas-7':
        print('ODD',t['rating_id'],t['displayed_label'],t['judge_model'],m,a,t['judge_output'])
for r in rows:
    t=tmap.get(r['rating_id'])
    if t is None: print('missing',r); bad+=1; continue
    m=re.findall(r'FINAL SCORE:\s*(\S+)',t['judge_output'])
    if int(r['score'])!=int(m[-1]) or r['displayed_label']!=t['displayed_label'] or r['response_id']!=t['response_id'] or int(r['session'])!=t['session']:
        print('MISMATCH',r,t['displayed_label'],m); bad+=1
print('bad',bad)
print(collections.Counter((r['session'],r['displayed_label']) for r in rows))
print(collections.Counter(r['response_id'] for r in rows).most_common(3))
for t in tr:
    if len(t['judge_output'])>0 and 'FINAL' not in t['judge_output']: print(t)

