import json,csv,collections,statistics as st
rows=list(csv.DictReader(open('data/scores.csv')))
tr=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
for t in tr: print(t['rating_id'],t['response_id'],t['session'],t['displayed_label'],'|',t['judge_output'])
by=collections.defaultdict(dict)
for r in rows: by[r['response_id']][r['displayed_label']]=int(r['score'])
diffs=[]
for k,v in sorted(by.items()):
    if set(v)!={'atlas-7','nova-3'}: print('unpaired',k,v)
    else: diffs.append(v['atlas-7']-v['nova-3'])
print(len(diffs), sum(diffs)/len(diffs), round(sum(diffs)/len(diffs),2))
print(collections.Counter(diffs))
rs=[json.loads(l) for l in open('data/responses.jsonl')]
